// Enemy kinds. `key` is the sprite sheet (frames: pose A, pose B, explosion);
// sheets other than the original are generated by tools/make_sprites.py.
var ENEMY_TYPES = {
  grunt: { key: 'enemy', hp: 1, points: 20, fireWeight: 1, diveWeight: 1, diveSpeed: 1 },
  // Small and fast: rarely shoots but dives often and quickly.
  scout: { key: 'enemy-scout', hp: 1, points: 30, fireWeight: 0.5, diveWeight: 3, diveSpeed: 1.35 },
  // Purple invader: the sharpshooter of the formation.
  elite: { key: 'enemy-elite', hp: 1, points: 40, fireWeight: 2.5, diveWeight: 1, diveSpeed: 1.1 },
  // Armored saucer: takes two hits, slow to dive.
  tank: { key: 'enemy-tank', hp: 2, points: 60, fireWeight: 1.5, diveWeight: 0.4, diveSpeed: 0.8 }
};

var ENEMY_SHEETS = ['enemy', 'enemy-scout', 'enemy-elite', 'enemy-tank'];

// Which kinds can appear, and how often, in a given wave.
function enemyMix(wave) {
  var mix = { grunt: 6, scout: 2 };
  if (wave >= 2) mix.elite = 2;
  if (wave >= 3) mix.tank = Math.min(wave - 2, 4);
  return mix;
}

function weightedPick(items, weightOf) {
  var total = 0;
  items.forEach(function (item) { total += weightOf(item); });
  var r = Math.random() * total;
  for (var i = 0; i < items.length; i++) {
    r -= weightOf(items[i]);
    if (r < 0) return items[i];
  }
  return items[items.length - 1];
}

// One kind per row (slots at about the same height), so mirrored shapes stay
// symmetric and formations look designed rather than noisy.
function assignEnemyTypes(slots, wave) {
  var mix = enemyMix(wave);
  var kinds = Object.keys(mix);
  var rows = {};
  slots.forEach(function (slot) {
    var row = Math.round(slot.y / 20);
    (rows[row] = rows[row] || []).push(slot);
  });
  Object.keys(rows).forEach(function (row) {
    var kind = ENEMY_TYPES[weightedPick(kinds, function (k) { return mix[k]; })];
    rows[row].forEach(function (slot) { slot.kind = kind; });
  });
  return slots;
}
